def run_experiment(config, input_data):
    if type(config.get('trials')) is not int or not 1 <= config['trials'] <= 100:
        raise ValueError('trials must be an integer between 1 and 100')
    if type(config.get('seed')) is not int:
        raise ValueError('seed must be an integer')
    rng = random.Random(config['seed'])
    records = []
    for trial in range(config['trials']):
        sample = [rng.gauss(0, 1) for _ in range(19)] + [10.0]
        for name, fn in [('mean', statistics.mean), ('median', statistics.median)]:
            records.append({'trial': trial, 'method': name, 'absolute_error': abs(fn(sample))})
    return records

